package io.github.denberg28.telerc
import org.junit.Assert.*
import org.junit.Test
import java.io.ByteArrayInputStream

class GoUpdateRulesTest {
 private val hash="ab".repeat(32)
 private fun candidate(tag:String="go-v1.0.4",current:String="1.0.3",draft:Boolean=false,pre:Boolean=false,name:String="TeleRC-Go-v1.0.4.apk",url:String="https://github.com/Denberg28/TeleRC/releases/download/go-v1.0.4/TeleRC-Go-v1.0.4.apk",digest:String="sha256:$hash",bytes:Long=1_000_000)=GoUpdateRules.candidate(tag,current,draft,pre,name,url,digest,bytes)
 @Test fun onlyNewerStableGoAssetIsAnUpdate(){assertEquals("1.0.4",candidate()?.version);assertNull(candidate(tag="v9.0.0"));assertNull(candidate(current="1.0.4"));assertNull(candidate(current="2.0.0"));assertNull(candidate(draft=true));assertNull(candidate(pre=true));assertNull(candidate(name="TeleRC-v1.0.4.apk"));assertNull(candidate(tag="go-v1.0.4-rc1"));assertNull(candidate(tag="go-v1.0.4/other"))}
 @Test fun numericVersionOrderAndStrictTags(){assertTrue(GoUpdateRules.compare("1.0.10","1.0.9")>0);assertTrue(GoUpdateRules.compare("2.0.0","1.99.99")>0);assertEquals(0,GoUpdateRules.compare("1.0.3","1.0.3"));for(tag in listOf("v1.0.4","go-v1.0","go-v1.0.4-dev","go-v9999999.0.0","go-v-1.0.0","go-v1.0.0.1"))assertNull(GoUpdateRules.tagVersion(tag))}
 @Test fun assetOriginVersionHashAndBoundsMustMatch(){for(url in listOf("http://github.com/Denberg28/TeleRC/releases/download/go-v1.0.4/TeleRC-Go-v1.0.4.apk","https://github.com.evil.test/Denberg28/TeleRC/releases/download/go-v1.0.4/TeleRC-Go-v1.0.4.apk","https://github.com/Denberg28/TeleRC/releases/download/go-v1.0.4/TeleRC-Go-v1.0.4.apk?url=other","https://github.com/Other/TeleRC/releases/download/go-v1.0.4/TeleRC-Go-v1.0.4.apk"))assertNull(candidate(url=url));assertNull(candidate(digest="sha256:"+"z".repeat(64)));assertNull(candidate(digest="sha1:$hash"));assertNull(candidate(bytes=99_999));assertNull(candidate(bytes=50_000_001));assertNotNull(candidate(bytes=100_000));assertNotNull(candidate(bytes=50_000_000))}
 @Test fun archiveRequiresSamePackageNewerCodeAndExactNonemptySignerSet(){val p="io.github.denberg28.telerc.go";val s=setOf("retained");assertTrue(GoUpdateRules.archiveAllowed(p,p,5,4,s,s));assertFalse(GoUpdateRules.archiveAllowed("io.github.denberg28.telerc",p,999,4,s,s));assertFalse(GoUpdateRules.archiveAllowed(p,p,4,4,s,s));assertFalse(GoUpdateRules.archiveAllowed(p,p,3,4,s,s));assertFalse(GoUpdateRules.archiveAllowed(p,p,5,4,setOf("other"),s));assertFalse(GoUpdateRules.archiveAllowed(p,p,5,4,emptySet(),emptySet()));assertFalse(GoUpdateRules.archiveAllowed(p,p,5,4,null,s))}
 @Test fun metadataLimitPreservesUtf8AndStopsGrowingInput(){val text=" ".repeat(8191)+"✓ Go";assertEquals(text,GoUpdateRules.read(ByteArrayInputStream(text.toByteArray())));assertEquals(GoUpdateRules.MAX_METADATA_BYTES,GoUpdateRules.read(ByteArrayInputStream(ByteArray(GoUpdateRules.MAX_METADATA_BYTES){32})).length);assertThrows(IllegalArgumentException::class.java){GoUpdateRules.read(ByteArrayInputStream(ByteArray(GoUpdateRules.MAX_METADATA_BYTES+1)))};var read=0;val endless=object:java.io.InputStream(){override fun read():Int{read++;return 32}};assertThrows(IllegalArgumentException::class.java){GoUpdateRules.read(endless)};assertTrue(read<=GoUpdateRules.MAX_METADATA_BYTES+8192)}
}
